// Generates a deployment-wide session secret.
//
// Vercel may run several serverless instances for one deployment. If each
// instance created its own secret in /tmp, a token signed by one instance would
// be rejected by the next, which surfaced as "Your session has expired" right
// after signing in. Generating the secret during the build and importing it
// into the function bundle gives every instance of a deployment the same key.
//
// SESSION_SECRET still wins when it is set, which keeps sessions alive across
// deployments. The generated file is git-ignored and never shipped to clients.
import { randomBytes } from "node:crypto";
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const target = path.resolve(here, "..", "server", "session-secret.js");

if (existsSync(target)) {
  process.exit(0);
}

const secret = randomBytes(48).toString("hex");
writeFileSync(
  target,
  `// Auto-generated by scripts/generate-session-secret.mjs. Do not commit.\n` +
    `export const GENERATED_SESSION_SECRET = "${secret}";\n`,
  { encoding: "utf8", mode: 0o600 },
);

console.log("[session-secret] generated server/session-secret.js");
